/**
 * Compile-time bridge between the hand-written UI types and the backend
 * contract, until every page reads the generated types directly (F23 阶段 6).
 *
 * `schema.d.ts` is generated by `npm run codegen` from
 * `backend/tests/openapi_snapshot.json` — the one contract copy that a backend
 * test keeps honest. Before this file existed, drift was an *after-the-fact*
 * alarm: the snapshot test failed and told a human to go edit `types.ts`.
 * Here it is a build failure instead.
 *
 * What it catches: a hand-written type claiming a field the contract no longer
 * has — the rename/removal case, where the UI keeps mirroring a name the
 * backend dropped.
 *
 * What it deliberately does not catch: fields the contract has and the UI
 * ignores (the UI is allowed to read less), and optionality differences.
 * FastAPI marks any field with a default as optional in OpenAPI even though the
 * serializer always emits it, so requiring exact optionality would flag noise
 * rather than drift.
 */
import type { components } from "./schema";
import type {
  AggregationLabelCatalog,
  AggregationRule,
  AggregationRulePreview,
  AlertOut,
  EventSource,
  EventSourceAudit,
  EventSourceConfig,
  EventSourceEndpoint,
  EventSourceTestResult,
  EventSourceGrafana,
  EventSourceThanos,
  GrafanaDashboardSummary,
  GrafanaImportPreview,
  HandlingAudit,
  Health,
  ImportCandidate,
  IncidentDetail,
  IncidentNotification,
  IncidentOccurrence,
  IncidentOccurrencePage,
  IncidentSummary,
  NotificationAttempt,
  NotificationChannel,
  NotificationChannelRevision,
  NotificationDelivery,
  NotificationDeliveryDetail,
  NotificationPolicy,
  NotificationPolicyPreview,
  ModelChannel,
  ModelChannelRevision,
  SourcePollHealth,
  SourceScope,
  WatchdogCluster,
  WatchdogSourceClusterHealth,
  WatchdogSourceHealth,
} from "../types";

type Schemas = components["schemas"];

/** Hand-written keys the contract does not have. */
type ExtraKeys<Hand, Contract> = Exclude<keyof Hand, keyof Contract>;

type Bridge = {
  IncidentSummary: [IncidentSummary, Schemas["IncidentSummary"]];
  IncidentDetail: [IncidentDetail, Schemas["IncidentDetail"]];
  AlertOut: [AlertOut, Schemas["AlertOut"]];
  HandlingAudit: [HandlingAudit, Schemas["HandlingAuditOut"]];
  Health: [Health, Schemas["Health"]];
  SourcePollHealth: [SourcePollHealth, Schemas["SourcePollHealth"]];
  WatchdogSourceHealth: [WatchdogSourceHealth, Schemas["WatchdogSourceHealth"]];
  WatchdogSourceClusterHealth: [
    WatchdogSourceClusterHealth,
    Schemas["WatchdogSourceClusterHealth"],
  ];
  WatchdogCluster: [WatchdogCluster, Schemas["WatchdogClusterOut"]];
  AggregationRule: [AggregationRule, Schemas["AggregationRuleOut"]];
  AggregationRulePreview: [AggregationRulePreview, Schemas["AggregationRulePreviewOut"]];
  AggregationLabelCatalog: [AggregationLabelCatalog, Schemas["AggregationLabelCatalogOut"]];
  SourceScope: [SourceScope, Schemas["SourceScope"]];
  EventSource: [EventSource, Schemas["EventSourceOut"]];
  EventSourceConfig: [EventSourceConfig, Schemas["EventSourceConfigOut"]];
  EventSourceEndpoint: [EventSourceEndpoint, Schemas["EventSourceEndpointOut"]];
  EventSourceThanos: [EventSourceThanos, Schemas["EventSourceThanosOut"]];
  EventSourceGrafana: [EventSourceGrafana, Schemas["EventSourceGrafanaOut"]];
  GrafanaDashboardSummary: [
    GrafanaDashboardSummary,
    Schemas["GrafanaDashboardSummaryOut"],
  ];
  GrafanaImportPreview: [GrafanaImportPreview, Schemas["GrafanaImportPreviewOut"]];
  ImportCandidate: [ImportCandidate, Schemas["ImportCandidateOut"]];
  EventSourceTestResult: [EventSourceTestResult, Schemas["EventSourceTestOut"]];
  EventSourceAudit: [EventSourceAudit, Schemas["EventSourceAuditOut"]];
  NotificationChannel: [NotificationChannel, Schemas["ChannelOut"]];
  NotificationChannelRevision: [NotificationChannelRevision, Schemas["ChannelRevisionOut"]];
  ModelChannel: [ModelChannel, Schemas["ModelChannelOut"]];
  ModelChannelRevision: [ModelChannelRevision, Schemas["ModelChannelRevisionOut"]];
  NotificationPolicy: [NotificationPolicy, Schemas["PolicyOut"]];
  NotificationPolicyPreview: [NotificationPolicyPreview, Schemas["PolicyPreviewOut"]];
  NotificationDelivery: [NotificationDelivery, Schemas["DeliveryOut"]];
  NotificationDeliveryDetail: [NotificationDeliveryDetail, Schemas["DeliveryDetailOut"]];
  NotificationAttempt: [NotificationAttempt, Schemas["AttemptOut"]];
  IncidentNotification: [IncidentNotification, Schemas["IncidentNotificationOut"]];
  IncidentOccurrence: [IncidentOccurrence, Schemas["IncidentOccurrenceOut"]];
  IncidentOccurrencePage: [IncidentOccurrencePage, Schemas["IncidentOccurrencePage"]];
};

/**
 * The names of every hand-written type that claims a field the contract lacks.
 * `never` when the mirror is honest — and the assertion below only compiles
 * then, so a drifted name shows up in the build error.
 */
export type ContractDrift = {
  [K in keyof Bridge]: [ExtraKeys<Bridge[K][0], Bridge[K][1]>] extends [never] ? never : K;
}[keyof Bridge];

export const contractIsHonest: [ContractDrift] extends [never] ? true : never = true;
